class Solution {
  private static long cost(long x, long mask) {
    if ((x & mask) == mask) return 0;
    long best = Long.MAX_VALUE;
    for (int p = 0; p < 40; p++) {
      if ((x >> p & 1) != 0) continue;
      long upperX = x >> (p + 1), upperMask = mask >> (p + 1);
      if ((upperX & upperMask) != upperMask) continue;
      long y = (upperX << (p + 1)) | (1L << p) | (mask & ((1L << p) - 1));
      if (y >= x) best = Math.min(best, y);
    }
    return best - x;
  }

  public int maximumAND(int[] nums, int k, int m) {
    int n = nums.length;
    long ans = 0;
    long[] costs = new long[n];
    for (int bit = 31; bit >= 0; bit--) {
      long cand = ans | (1L << bit);
      for (int i = 0; i < n; i++) costs[i] = cost(nums[i], cand);
      long[] copy = costs.clone();
      java.util.Arrays.sort(copy);
      long total = 0;
      for (int i = 0; i < m; i++) {
        total += copy[i];
        if (total > k) break;
      }
      if (total <= k) ans = cand;
    }
    return (int) ans;
  }
}
